declare const UserIdBrand: unique symbol;
declare const OrderIdBrand: unique symbol;

type UserId = string & { readonly [UserIdBrand]: true };
type OrderId = string & { readonly [OrderIdBrand]: true };

function parseUserId(raw: string): UserId | null {
  return /^usr_[a-z0-9]+$/.test(raw) ? (raw as UserId) : null;
}

function deleteUser(id: UserId): Promise<void> {
  return fetch(`/api/users/${id}`, { method: 'DELETE' }).then(() => {});
}

