declare const EmailTag: unique symbol;
export type Email = string & { readonly [EmailTag]: true };

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

export function Email(raw: string): Email | null {
  const normalized = raw.trim().toLowerCase();
  return EMAIL_RE.test(normalized) ? (normalized as Email) : null;
}

