type Subject = string & { readonly __brand: 'JwtSubject' };

function parseSubject(payload: unknown): Subject | null {
  if (typeof payload !== 'object' || payload === null) return null;
  const sub = (payload as { sub?: unknown }).sub;
  return typeof sub === 'string' && sub.length > 0 ? (sub as Subject) : null;
}

async function loadSession(subject: Subject) {
  const cached = await redis.get(`session:${subject}`);
  return cached ? JSON.parse(cached) : fetch(`/api/session/${subject}`);
}

